-- Aura 67: bloqueio entre pessoas e denúncias de mensagens privadas. Execute depois da 026.
create table if not exists public.user_blocks(blocker_id uuid not null references public.profiles(id) on delete cascade,blocked_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(blocker_id,blocked_id),check(blocker_id<>blocked_id));
create table if not exists public.direct_message_reports(id uuid primary key default gen_random_uuid(),message_id bigint not null references public.direct_messages(id) on delete cascade,reporter_id uuid not null references public.profiles(id) on delete cascade,reason text not null check(reason in('spam','assedio','odio','sexual','golpe','outro')),details text check(char_length(details)<=500),status text not null default 'pending' check(status in('pending','reviewed','dismissed','actioned')),created_at timestamptz not null default now(),unique(message_id,reporter_id));
alter table public.user_blocks enable row level security;alter table public.direct_message_reports enable row level security;revoke all on public.user_blocks,public.direct_message_reports from anon,authenticated;
create or replace function public.toggle_user_block(p_profile_id uuid,p_block boolean) returns boolean language plpgsql security definer set search_path='' as $$declare v_user uuid:=auth.uid();begin if v_user is null or p_profile_id=v_user or not exists(select 1 from public.profiles where id=p_profile_id) then raise exception 'Perfil inválido';end if;if p_block then insert into public.user_blocks(blocker_id,blocked_id)values(v_user,p_profile_id)on conflict do nothing;else delete from public.user_blocks where blocker_id=v_user and blocked_id=p_profile_id;end if;return p_block;end;$$;
create or replace function public.get_direct_block_status(p_profile_id uuid) returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('blocked_by_me',exists(select 1 from public.user_blocks where blocker_id=auth.uid() and blocked_id=p_profile_id),'blocked_me',exists(select 1 from public.user_blocks where blocker_id=p_profile_id and blocked_id=auth.uid()));$$;
create or replace function public.report_direct_message(p_message_id bigint,p_reason text,p_details text default null) returns uuid language plpgsql security definer set search_path='' as $$declare v_user uuid:=auth.uid();v_id uuid;begin if p_reason not in('spam','assedio','odio','sexual','golpe','outro') then raise exception 'Motivo inválido';end if;if not exists(select 1 from public.direct_messages m join public.direct_conversations c on c.id=m.conversation_id where m.id=p_message_id and m.sender_id<>v_user and v_user in(c.user_a,c.user_b)) then raise exception 'Mensagem não encontrada';end if;insert into public.direct_message_reports(message_id,reporter_id,reason,details)values(p_message_id,v_user,p_reason,nullif(left(trim(p_details),500),''))on conflict(message_id,reporter_id)do update set reason=excluded.reason,details=excluded.details returning id into v_id;return v_id;end;$$;
create or replace function public.send_direct_message(p_conversation_id uuid,p_content text) returns bigint language plpgsql security definer set search_path='' as $$declare v_user uuid:=auth.uid();v_text text:=trim(p_content);v_id bigint;v_other uuid;begin select case when c.user_a=v_user then c.user_b else c.user_a end into v_other from public.direct_conversations c where c.id=p_conversation_id and v_user in(c.user_a,c.user_b);if v_other is null then raise exception 'Conversa não encontrada';end if;if exists(select 1 from public.user_blocks where(blocker_id=v_user and blocked_id=v_other)or(blocker_id=v_other and blocked_id=v_user))then raise exception 'Esta conversa está bloqueada';end if;if char_length(v_text)not between 1 and 1000 then raise exception 'Mensagem inválida';end if;insert into public.direct_messages(conversation_id,sender_id,content)values(p_conversation_id,v_user,v_text)returning id into v_id;update public.direct_conversations set updated_at=now()where id=p_conversation_id;return v_id;end;$$;
create or replace function public.send_direct_attachment(p_conversation_id uuid,p_storage_path text,p_original_name text,p_mime_type text,p_size_bytes bigint,p_caption text default null)returns bigint language plpgsql security definer set search_path='' as $$declare v_user uuid:=auth.uid();v_other uuid;v_message bigint;v_text text:=coalesce(nullif(trim(p_caption),''),'Arquivo: '||trim(p_original_name));begin select case when c.user_a=v_user then c.user_b else c.user_a end into v_other from public.direct_conversations c where c.id=p_conversation_id and v_user in(c.user_a,c.user_b);if v_other is null then raise exception 'Conversa não encontrada';end if;if exists(select 1 from public.user_blocks where(blocker_id=v_user and blocked_id=v_other)or(blocker_id=v_other and blocked_id=v_user))then raise exception 'Esta conversa está bloqueada';end if;if p_storage_path not like v_user::text||'/direct/'||p_conversation_id::text||'/%' then raise exception 'Caminho de anexo inválido';end if;if not exists(select 1 from storage.objects where bucket_id='chat-attachments' and name=p_storage_path and owner_id=v_user::text)then raise exception 'Upload privado não encontrado';end if;if p_mime_type not in('image/jpeg','image/png','image/webp','application/pdf')or p_size_bytes<1 or p_size_bytes>(case when p_mime_type like 'image/%' then 10485760 else 20971520 end)then raise exception 'Arquivo não permitido';end if;insert into public.direct_messages(conversation_id,sender_id,content)values(p_conversation_id,v_user,left(v_text,1000))returning id into v_message;insert into public.direct_message_attachments(message_id,conversation_id,sender_id,storage_path,original_name,mime_type,size_bytes)values(v_message,p_conversation_id,v_user,p_storage_path,left(trim(p_original_name),180),p_mime_type,p_size_bytes);update public.direct_conversations set updated_at=now()where id=p_conversation_id;return v_message;end;$$;
revoke all on function public.toggle_user_block(uuid,boolean),public.get_direct_block_status(uuid),public.report_direct_message(bigint,text,text) from public,anon;grant execute on function public.toggle_user_block(uuid,boolean),public.get_direct_block_status(uuid),public.report_direct_message(bigint,text,text) to authenticated;
create or replace function public.get_admin_direct_message_reports() returns table(report_id uuid,reason text,details text,message_content text,reported_at timestamptz,sender_name text,reporter_name text)language sql stable security definer set search_path='' as $$select r.id,r.reason,r.details,m.content,r.created_at,s.full_name,p.full_name from public.direct_message_reports r join public.direct_messages m on m.id=r.message_id join public.profiles s on s.id=m.sender_id join public.profiles p on p.id=r.reporter_id where public.is_aura_admin() and r.status='pending' order by r.created_at;$$;
create or replace function public.resolve_direct_message_report(p_report_id uuid,p_action boolean)returns void language plpgsql security definer set search_path='' as $$begin if not public.is_aura_admin()then raise exception 'Acesso administrativo necessário';end if;update public.direct_message_reports set status=case when p_action then 'actioned' else 'dismissed' end where id=p_report_id;end;$$;
revoke all on function public.get_admin_direct_message_reports(),public.resolve_direct_message_report(uuid,boolean) from public,anon;grant execute on function public.get_admin_direct_message_reports(),public.resolve_direct_message_report(uuid,boolean) to authenticated;
